mapper.select:
SELECT 
  FROM sys06_menu m
       LEFT JOIN sys07_role_menu r ON r.sys07_menu_id = m.sys06_menu_id AND r.sys07_role_id = #{roleId}
 WHERE m.sys06_menu_id = #{menuId}

SELECT sys06_menu_id AS menu_id, sys06_parent_path_nm AS parent_path_nm, sys06_menu_no_plus_nm AS menu_no_plus_nm FROM ( SELECT a.* , f_menu_nm_allpath(a.sys06_menu_id) AS sys06_menu_full_nm , TRIM(TRAILING sys06_menu_nm FROM f_menu_nm_allpath(a.sys06_menu_id)) AS sys06_parent_path_nm , (CASE WHEN sys06_menu_no IS NULL THEN sys06_menu_nm ELSE sys06_menu_no || ' ' || sys06_menu_nm END) AS sys06_menu_no_plus_nm FROM sys06_menu a WHERE sys06_parent_id != 0 AND sys06_parent_id NOT IN (SELECT sys06_menu_id FROM sys06_menu WHERE sys06_parent_id = 0) ) t WHERE 1=1
AND sys06_menu_no_plus_nm ILIKE #{searchText}
AND CONCAT(sys06_menu_full_nm, sys06_note, sys06_menu_no) ILIKE #{searchText}
ORDER BY sys06_parent_id, sys06_seq, sys06_menu_full_nm

SELECT sys06_menu_id AS menu_id, sys06_parent_path_nm AS parent_path_nm, sys06_menu_nm AS menu_nm, sys06_menu_full_nm AS menu_full_nm FROM ( SELECT a.* , f_menu_nm_allpath(a.sys06_menu_id) AS sys06_menu_full_nm , TRIM(TRAILING sys06_menu_nm FROM f_menu_nm_allpath(a.sys06_menu_id)) AS sys06_parent_path_nm , (CASE WHEN sys06_menu_no IS NULL THEN sys06_menu_nm ELSE sys06_menu_no || ' ' || sys06_menu_nm END) AS sys06_menu_no_plus_nm FROM sys06_menu a WHERE sys06_parent_id != 0 AND sys06_parent_id NOT IN (SELECT sys06_menu_id FROM sys06_menu WHERE sys06_parent_id = 0) ) t WHERE 1=1
AND sys06_menu_no_plus_nm ILIKE #{searchText}
AND CONCAT(sys06_menu_full_nm, sys06_note, sys06_menu_no) ILIKE #{searchText}
ORDER BY sys06_parent_id, sys06_seq, sys06_menu_full_nm

SELECT COUNT(a.*)
  FROM sys03_company_menu a
       INNER JOIN sys06_menu b ON a.sys03_menu_id = b.sys06_menu_id
 WHERE b.sys06_parent_id  = #{parentId}
   AND a.sys03_company_id = #{companyId}
   AND COALESCE(a.sys03_use_yn, 'false') = 'true'

